import { useMemo } from 'react';

export type BackgroundTheme = 'cyber' | 'aurora' | 'minimal' | 'sunset' | 'ocean';

interface Orb {
  id: number;
  x: number;
  y: number;
  size: number;
  color: string;
  delay: number;
  duration: number;
}

const themeColors: Record<BackgroundTheme, string[]> = {
  cyber: [
    'hsl(217 91% 60% / 0.15)',
    'hsl(38 92% 50% / 0.12)',
    'hsl(280 70% 50% / 0.1)',
    'hsl(160 70% 40% / 0.08)',
  ],
  aurora: [
    'hsl(160 70% 50% / 0.15)',
    'hsl(200 80% 50% / 0.12)',
    'hsl(280 60% 60% / 0.1)',
    'hsl(320 70% 50% / 0.08)',
  ],
  minimal: [
    'hsl(0 0% 50% / 0.08)',
    'hsl(0 0% 40% / 0.06)',
    'hsl(0 0% 60% / 0.05)',
    'hsl(0 0% 30% / 0.04)',
